import { Link, useHistory } from "react-router-dom";
import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import { getAllCars, deleteCarById } from "../../services/ApiCar";
import moment from "moment";

export default function CardVoiture({ color = "light" }) {
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const history = useHistory();

  const fetchCars = async () => {
    try {
      setLoading(true);
      const res = await getAllCars();
      setCars(res.data);
    } catch (err) {
      setError("Erreur lors du chargement des voitures");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const deleteCar = async (id) => {
    if (window.confirm("Êtes-vous sûr de vouloir supprimer cette voiture ?")) {
      try {
        await deleteCarById(id);
        fetchCars();
      } catch (err) {
        setError("Erreur lors de la suppression");
        console.error(err);
      }
    }
  };

  useEffect(() => {
    fetchCars();
  }, []);

  if (loading) {
    return <div className="text-center py-8"><p>Chargement en cours...</p></div>;
  }

  if (error) {
    return (
      <div className="text-center py-8 text-red-500">
        <p>{error}</p>
        <button onClick={fetchCars} className="mt-2 bg-blue-500 text-white px-4 py-2 rounded">
          Réessayer
        </button>
      </div>
    );
  }

  return (
    <div className={`relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded ${
      color === "light" ? "bg-white" : "bg-lightBlue-900 text-white"
    }`}>
      {/* ... (le reste de l'en-tête identique) ... */}

      <tbody>
        {cars.map((car) => (
          <tr key={car._id} className="hover:bg-gray-50">
            {/* ... (autres cellules) ... */}
            <td className="border-t-0 px-6 py-4 align-middle text-center">
              <div className="flex items-center justify-center gap-2">
                <Link to={{
                  pathname: "/admin/UpdateVoiture",
                  state: { car }
                }}>
                  <button className="bg-blue-500 hover:bg-blue-600 text-white text-xs font-semibold py-2 px-3 rounded-full shadow transition duration-300">
                    ✏️ Modifier
                  </button>
                </Link>
                <button
                  onClick={() => deleteCar(car._id)}
                  className="bg-red-500 hover:bg-red-600 text-white text-xs font-semibold py-2 px-3 rounded-full shadow transition duration-300"
                >
                  🗑️ Supprimer
                </button>
              </div>
            </td>
          </tr>
        ))}
      </tbody>
    </div>
  );
}

CardVoiture.propTypes = {
  color: PropTypes.oneOf(["light", "dark"]),
};
